	(2, 'Ontario', 'civil-estates', 'Ontario Estate Forms under Rules 74, 74.1 and 75', 'https://ontariocourtforms.on.ca/en/rules-of-civil-procedure-forms/pre-formatted-fillable-estates-forms/', 'official forms', 'Official estate/probate forms under the Rules of Civil Procedure.', '2026-04-27 21:27:28.147283+00'),
	(3, 'Ontario', 'civil', 'Ontario Superior Court - Steps to a Civil Case', 'https://www.ontariocourts.ca/scj/guides-and-service-resources/guide-to-representing-yourself/civil-resources-to-help-self-represented-litigants/steps-to-civil-case/', 'official procedure guide', 'Used for procedure-stage mapping, not as a form download source.', '2026-04-27 21:27:28.147283+00'),
	(4, 'Ontario', 'civil', 'Ontario Rules of Civil Procedure Regulation', 'https://www.ontario.ca/laws/regulation/900194', 'official law', 'Used to map forms to rules and procedural stages.', '2026-04-27 21:27:28.147283+00'),
