INSERT INTO "public"."legal_element_rules" ("id", "jurisdiction", "court_area", "issue_name", "issue_category", "legal_elements", "plain_language_explanation", "facts_needed", "evidence_needed", "defence_or_response_risks", "judge_focus_points", "drafting_guidance", "official_source_name", "official_source_url", "notes", "is_active", "created_at") VALUES
	(1, 'Ontario', 'small-claims', 'Unpaid invoice or unpaid money', 'money_claim', '{"existence of a payment obligation","amount owed",non-payment,"link between defendant and obligation"}', '{"You must prove someone owed you money","You must show how much they owe","You must show they did not pay"}', '{"what agreement created the debt","when payment was due","how much was agreed","any partial payments"}', '{invoice,"contract or messages","bank records","payment history"}', '{"no written agreement","unclear amount","payment dispute","wrong party named"}', '{"clear amount","clear obligation","clear non-payment"}', '{"state agreement","state amount","state non-payment clearly"}', 'Ontario Small Claims Court', 'https://www.ontario.ca/document/guide-procedures-small-claims-court', 'Core money claim logic', true, '2026-04-28 20:16:17.188434+00'),
	(2, 'Ontario', 'small-claims', 'Breach of contract or agreement', 'contract', '{"agreement exists","terms of agreement","breach of those terms","loss caused by breach"}', '{"You must prove there was a deal","You must show what was promised","You must show how it was broken","You must show what you lost"}', '{"what was agreed","who agreed","what went wrong","how the loss occurred"}', '{contract,messages,invoices,photos,"repair estimates"}', '{"unclear terms","no written proof","loss not connected to breach"}', '{"clarity of agreement","clear breach","clear damages"}', '{"describe agreement in plain facts","describe breach step-by-step"}', 'Ontario Small Claims Court', 'https://www.ontario.ca/document/guide-procedures-small-claims-court', 'Contract logic', true, '2026-04-28 20:16:17.188434+00'),
	(3, 'Ontario', 'small-claims', 'Property damage', 'damage', '{"damage occurred","defendant caused damage","amount of damage"}', '{"You must prove something was damaged","You must show who caused it","You must prove repair cost"}', '{"what was damaged","when it happened","how it happened"}', '{photos,"repair estimates",receipts,messages}', '{"no proof of damage","no proof of cause","guessing repair cost"}', '{"clear cause","clear damage","reasonable cost"}', '{"describe incident clearly","connect defendant to damage"}', 'Ontario Small Claims Court', 'https://www.ontariocourts.ca/scj/areas-of-law/small-claims-court/', 'Damage claim logic', true, '2026-04-28 20:16:17.188434+00'),
	(4, 'Ontario', 'small-claims', 'Defamation / reputational harm', 'defamation', '{"statement made","statement communicated to others","statement is false","harm caused"}', '{"You must show what was said","You must show others heard it","You must show it was false","You must show harm"}', '{"exact words","who heard it","when it was said"}', '{screenshots,messages,"witness proof"}', '{"truth defence","opinion defence","no harm proven"}', '{"exact wording matters","proof of publication matters"}', '{"quote exact words","state who received them"}', 'Ontario Civil Claims', 'https://www.ontario.ca/page/civil-claims-suing-and-being-sued', 'Defamation logic', true, '2026-04-28 20:16:17.188434+00'),
	(5, 'Ontario', 'family', 'Parenting / decision-making responsibility', 'parenting', '{"child best interests","current care arrangement","proposed arrangement","impact on child"}', '{"Court focuses on child, not parents","You must show what is best for the child"}', '{"child routine","who cares for child","school/health situation"}', '{"school records",messages,schedule}', '{"no child-focused facts","only conflict arguments"}', '{stability,safety,routine}', '{"write facts about child, not emotions"}', 'Ontario Family Court', 'https://www.ontario.ca/document/guide-procedures-family-court', 'Parenting logic', true, '2026-04-28 20:16:17.188434+00'),
	(6, 'Ontario', 'family', 'Child support', 'support', '{"income of parties","child needs","support calculation"}', '{"Support depends on income","Expenses must be proven"}', '{"income details","child expenses"}', '{"tax returns","pay stubs",receipts}', '{"missing financial disclosure","income unclear"}', '{"accurate income","clear expense proof"}', '{"state income clearly","attach financial proof"}', 'Ontario Family Court', 'https://www.ontario.ca/document/guide-procedures-family-court', 'Support logic', true, '2026-04-28 20:16:17.188434+00'),
	(7, 'Ontario', 'civil', 'Negligence / damages', 'negligence', '{"duty of care","breach of duty",causation,damages}', '{"You must show someone had responsibility","You must show they failed","You must show it caused harm","You must prove damage"}', '{"what duty existed","what went wrong","how harm occurred"}', '{photos,reports,records}', '{"causation unclear","no damages proof"}', '{"link between action and harm","clear damages"}', '{"connect facts step-by-step"}', 'Ontario Civil Claims', 'https://www.ontario.ca/page/civil-claims-suing-and-being-sued', 'Negligence logic', true, '2026-04-28 20:16:17.188434+00');
INSERT INTO "public"."legal_evidence_rules" ("id", "jurisdiction", "court_area", "issue_name", "evidence_category", "evidence_needed", "weak_evidence_warnings", "upload_prompts", "evidence_labels", "connects_to_forms", "court_use_notes", "is_active", "created_at") VALUES
	(1, 'Ontario', 'small-claims', 'Unpaid invoice or unpaid money', 'financial_proof', '{"invoice or written demand","contract or agreement","messages confirming payment obligation","bank records or e-transfer history","proof no payment was received"}', '{"no written invoice","no clear agreement on amount","partial payments not explained","cash payment with no record"}', '{"Upload invoices or payment requests","Upload messages discussing payment","Upload bank statements or e-transfer screenshots"}', '{Invoice,"Payment Agreement","Bank Record","Demand Letter"}', '{"Plaintiff’s Claim","Settlement Conference Package","Trial Evidence"}', '{"Court uses this to confirm money is owed and unpaid"}', true, '2026-04-28 18:52:22.700808+00'),
	(2, 'Ontario', 'small-claims', 'Breach of contract or agreement', 'contract_proof', '{"written or verbal agreement proof","terms of agreement","messages confirming expectations","proof of breach","loss or damage calculation"}', '{"unclear agreement terms","no written proof","no evidence of breach","damages not calculated"}', '{"Upload contract or quote","Upload messages showing agreement","Upload proof showing work not completed or done incorrectly"}', '{Contract,Quote,"Agreement Messages","Breach Evidence"}', '{"Plaintiff’s Claim","Settlement Conference Package"}', '{"Court needs to see agreement + breach + damages"}', true, '2026-04-28 18:52:22.700808+00'),
	(3, 'Ontario', 'small-claims', 'Property damage', 'damage_proof', '{"photos before and after damage","repair estimates",receipts,"messages about incident","witness statements"}', '{"no before photos","no repair estimate","unclear who caused damage","damage amount guessed"}', '{"Upload photos of damage","Upload repair quotes or receipts","Upload messages or reports about incident"}', '{"Damage Photos","Repair Estimate","Incident Messages"}', '{"Plaintiff’s Claim","Trial Evidence"}', '{"Court needs proof of damage, cause, and cost"}', true, '2026-04-28 18:52:22.700808+00'),
	(4, 'Ontario', 'small-claims', 'Defamation / reputational harm', 'publication_proof', '{"screenshots of statements","messages or posts","proof others saw/heard it","timeline of events","proof of harm or loss"}', '{"no exact wording","no proof it was shared with others","opinion vs fact confusion","no proof of harm"}', '{"Upload screenshots or messages","Upload proof showing others received or saw the statements","Upload any proof of financial or reputational harm"}', '{Screenshots,Messages,"Witness Proof","Damage Evidence"}', '{"Plaintiff’s Claim","Evidence Package"}', '{"Court requires exact words + publication + harm"}', true, '2026-04-28 18:52:22.700808+00'),
	(5, 'Ontario', 'family', 'Parenting / decision-making responsibility', 'parenting_proof', '{"current parenting schedule","school records","medical records","messages between parents","evidence of caregiving history"}', '{"no clear schedule","no child-focused evidence","only conflict evidence","no documentation of caregiving"}', '{"Upload parenting schedule","Upload school or daycare records","Upload messages about parenting"}', '{"Parenting Schedule","School Records","Parent Communication"}', '{"Parenting Affidavit","Case Conference Brief"}', '{"Court focuses on best interests of the child"}', true, '2026-04-28 18:52:22.700808+00'),
	(6, 'Ontario', 'family', 'Child support', 'income_proof', '{"tax returns","notices of assessment","pay stubs","expense receipts for child","bank statements"}', '{"missing tax documents","income unclear","no proof of expenses","outdated financial info"}', '{"Upload tax returns","Upload pay stubs","Upload child-related expenses"}', '{"Tax Return","Pay Stub","Expense Receipt"}', '{"Financial Statement","Conference Brief"}', '{"Court requires full financial disclosure"}', true, '2026-04-28 18:52:22.700808+00'),
	(7, 'Ontario', 'civil', 'Negligence / damages', 'liability_proof', '{"photos of incident",reports,messages,timeline,"proof of damages"}', '{"no clear cause of damage","no proof linking defendant to harm","damages not supported"}', '{"Upload incident photos","Upload reports or emails","Upload proof of damages"}', '{"Incident Evidence","Damage Proof",Timeline}', '{"Statement of Claim","Motion Materials"}', '{"Court needs duty + breach + causation + damages"}', true, '2026-04-28 18:52:22.700808+00'),
	(8, 'Ontario', 'civil', 'Enforcement after judgment', 'enforcement_proof', '{"judgment order","payment history","debtor information","amount remaining"}', '{"no judgment","unclear balance owing","no debtor info"}', '{"Upload court judgment","Upload payment records","Upload debtor information"}', '{Judgment,"Payment History","Debtor Info"}', '{Garnishment,"Enforcement Documents"}', '{"Court requires valid judgment and outstanding balance"}', true, '2026-04-28 18:52:22.700808+00');
