	(1, 'Ontario', 'small-claims', 'Unpaid invoice or unpaid money', 'money_claim', '{"unpaid invoice","did not pay","owes me money","refused to pay","unpaid work","unpaid services","loan not repaid"}', '{"who owes money","why money is owed","amount claimed","date payment was due","proof of agreement or obligation","proof of non-payment"}', '{"What exact amount is owed?","What was the agreement?","When was payment due?","Was partial payment made?","Was an invoice or demand sent?"}', '{invoice,contract,estimate,messages,"payment records","bank records","demand letter","proof of work completed"}', '{"unclear amount claimed","no proof of agreement","wrong legal name for defendant","limitation period concern"}', '{"Plaintiff’s Claim",Defence,"Settlement conference materials","Trial evidence package"}', '{"court needs a clear amount, legal basis for the debt, and proof supporting the calculation"}', 'Ontario Small Claims Court - Making a claim', 'https://www.ontario.ca/document/guide-procedures-small-claims-court/making-claim', 'Small Claims guide explains preparing a Plaintiff’s Claim and supporting the amount claimed.', true, '2026-04-28 18:38:26.073742+00'),
