	(17, 'Ontario', 'family', 'Urgent safety or family violence concern', 'urgent_safety', '{unsafe,violence,threats,abuse,harassment,fear,police,"emergency motion","urgent motion","without notice"}', '{"immediate risk","specific incidents","requested temporary order","evidence supporting urgency","notice issue"}', '{"What immediate harm is happening?","What happened and when?","Is there police or medical evidence?","What exact temporary order is needed?"}', '{"police reports",messages,photos,"medical records","witness details","prior orders","safety plan"}', '{"urgent motion without evidence","unclear requested order","notice/service issue","risk of exaggerating without dated proof"}', '{"Notice of Motion",Affidavit,"urgent motion materials","supporting exhibits"}', '{"court needs specific evidence of urgency, not general fear alone"}', 'Ontario Court of Justice - Motions', 'https://www.ontariocourts.ca/ocj/family-court/going-to-court/motions/', 'OCJ says motions require Form 14 and Form 14A; urgent motions need strong evidence and precise requested orders.', true, '2026-04-28 18:45:20.15666+00'),
