INSERT INTO "public"."legal_risk_rules" ("id", "jurisdiction", "court_area", "risk_name", "risk_category", "plain_language_triggers", "risk_explanation", "facts_to_check", "evidence_to_check", "warning_message", "severity", "related_forms", "suggested_next_steps", "judge_or_court_concerns", "official_source_name", "official_source_url", "notes", "is_active", "created_at") VALUES
	(1, 'Ontario', 'civil', 'Limitation period risk', 'deadline', '{"years ago","long time ago","old case","happened years",delay}', '{"Claims usually must be started within a legal time limit","Delay can result in losing the right to sue"}', '{"date of event","date of discovery of harm","date defendant identified"}', '{"timeline records",emails,reports}', '⚠️ You may be out of time to start this claim. Limitation periods may apply.', 'high', '{"Statement of Claim"}', '{"confirm key dates","assess discoverability","seek legal confirmation before filing"}', '{"court strictly enforces limitation deadlines"}', 'Limitations Act, 2002', 'https://www.ontario.ca/laws/statute/02l24', 'Major dismissal risk', true, '2026-04-28 20:28:56.239156+00'),
	(2, 'Ontario', 'small-claims', 'No proof of service', 'procedure', '{"filed claim",served,"sent documents","emailed documents"}', '{"Filing a claim is not enough","The other party must be properly served"}', '{"who was served","how they were served","when service occurred"}', '{"affidavit of service","delivery confirmation"}', '⚠️ Your case may fail if you cannot prove the other party was properly served.', 'high', '{"Affidavit of Service"}', '{"complete affidavit of service","confirm correct service method","verify address used"}', '{"court requires proof of notice before proceeding"}', 'Ontario Small Claims Court', 'https://www.ontario.ca/document/guide-procedures-small-claims-court/serving-documents', 'Service is mandatory', true, '2026-04-28 20:28:56.239156+00'),
	(3, 'Ontario', 'civil', 'Wrong party named', 'party_error', '{"company name","business name","not sure who to sue","wrong name"}', '{"The correct legal party must be named","Using a trade name instead of legal entity can invalidate the claim"}', '{"legal name of defendant","type of entity (person/corporation)","connection to dispute"}', '{contract,invoice,"corporate search"}', '⚠️ You may have named the wrong party. This can result in dismissal or delay.', 'high', '{"Statement of Claim"}', '{"verify legal name","check corporate registry","confirm correct defendant"}', '{"court must have proper parties before granting relief"}', 'Ontario Civil Claims', 'https://www.ontario.ca/page/civil-claims-suing-and-being-sued', 'Very common error', true, '2026-04-28 20:28:56.239156+00'),
	(4, 'Ontario', 'small-claims', 'No proof of damages', 'evidence', '{estimate,guess,approximate,"rough amount"}', '{"Courts require proof of loss","Amounts cannot be guessed"}', '{"how damages are calculated","actual repair or loss cost"}', '{receipts,"repair estimates",invoices}', '⚠️ Your claim amount may be rejected if not supported by evidence.', 'high', '{"Plaintiff’s Claim"}', '{"attach receipts","obtain repair estimates","calculate exact amount"}', '{"court requires proof of damages"}', 'Ontario Small Claims Court', 'https://www.ontariocourts.ca/scj/areas-of-law/small-claims-court/', 'Damage proof required', true, '2026-04-28 20:28:56.239156+00'),
	(5, 'Ontario', 'family', 'Urgent motion without evidence', 'urgency', '{urgent,emergency,"immediate danger"}', '{"Urgent motions require strong evidence","Courts will not grant urgency without proof"}', '{"what happened","when it happened","why it is urgent"}', '{"police reports",messages,photos}', '⚠️ Urgent motion may fail without clear evidence of immediate harm.', 'high', '{"Form 14","Form 14A"}', '{"gather proof of urgency","prepare affidavit evidence","explain urgency clearly"}', '{"court limits urgent relief to proven emergencies"}', 'Ontario Family Court', 'https://www.ontariocourts.ca/ocj/family-court/going-to-court/motions/', 'Urgency threshold', true, '2026-04-28 20:28:56.239156+00'),
	(6, 'Ontario', 'family', 'No financial disclosure for support', 'financial', '{support,"child support","spousal support"}', '{"Support decisions require full financial disclosure","Missing documents weakens case"}', '{income,expenses,"financial documents"}', '{"tax returns","pay stubs"}', '⚠️ Support claim may fail without proper financial disclosure.', 'high', '{"Form 13","Form 13.1"}', '{"prepare financial statement","attach income documents"}', '{"court requires financial transparency"}', 'Ontario Family Court', 'https://www.ontario.ca/document/guide-procedures-family-court/financial-disclosure', 'Disclosure required', true, '2026-04-28 20:28:56.239156+00'),
	(7, 'Ontario', 'civil', 'Weak injunction request', 'injunction', '{"stop them",injunction,"urgent order"}', '{"Injunctions require strong legal test","Weak evidence may result in denial"}', '{harm,urgency,"balance of convenience"}', '{"affidavit evidence","supporting documents"}', '⚠️ Injunction may fail without strong evidence and legal basis.', 'high', '{"Notice of Motion"}', '{"strengthen evidence","clarify harm","prepare affidavit"}', '{"court applies strict test for injunctions"}', 'Rules of Civil Procedure', 'https://ontariocourtforms.on.ca/en/rules-of-civil-procedure-forms/', 'High threshold', true, '2026-04-28 20:28:56.239156+00'),
	(8, 'Ontario', 'civil', 'Appeal deadline risk', 'deadline', '{appeal,"challenge decision","wrong judgment"}', '{"Appeals have strict deadlines","Missing deadline can end appeal rights"}', '{"date of decision","appeal timeline"}', '{"court order","judgment date"}', '⚠️ You may miss your right to appeal if deadlines are not met.', 'high', '{"Notice of Appeal"}', '{"confirm appeal deadline","prepare notice quickly"}', '{"appeal courts enforce deadlines strictly"}', 'Court of Appeal', 'https://www.ontariocourts.ca/coa/how-to-proceed-court/', 'Strict timing', true, '2026-04-28 20:28:56.239156+00');
